from threading import Lock


def rate_limit(leak_rate, capacity, clock):
    if leak_rate <= 0:
        raise ValueError("leak_rate must be positive")
    if capacity < 0:
        raise ValueError("capacity cannot be negative")

    def decorator(func):
        state = {"tokens": float(capacity), "updated_at": None}
        lock = Lock()

        @wraps(func)
        def wrapper(*args, **kwargs):
            now = clock()
            with lock:
                if state["updated_at"] is None:
                    state["updated_at"] = now
                else:
                    elapsed = max(0.0, now - state["updated_at"])
                    state["tokens"] = min(
                        float(capacity),
                        state["tokens"] + elapsed * leak_rate,
                    )
                    state["updated_at"] = now

                if state["tokens"] < 1.0:
                    return False
                state["tokens"] -= 1.0

            return func(*args, **kwargs)

        return wrapper

    return decorator

